#include <iostream>
#include <iomanip>

int main() {
    // Reading slope inputs
    double x1 = 0.0, y1 = 0.0, x2 = 0.0, y2 = 0.0;
    if (std::cin >> x1 >> y1 >> x2 >> y2) {
        double slope = (y2 - y1) / (x2 - x1);
        std::cout << "The slope is " << slope << "\n";
    }

    // Reading driving cost inputs
    double distance = 0.0, mpg = 0.0, pricePerGallon = 0.0;
    if (std::cin >> distance >> mpg >> pricePerGallon) {
        double totalCost = (distance / mpg) * pricePerGallon;
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "The cost of driving is $" << totalCost << "\n";
    }

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    // Financial: Future investment calculation
    double investmentAmount = 0.0;
    double annualRate = 0.0;
    int years = 0;

    if (std::cin >> investmentAmount >> annualRate >> years) {
        double monthlyRate = annualRate / 1200.0;
        double futureValue = investmentAmount * std::pow(1.0 + monthlyRate, years * 12.0);
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "Accumulated value is $" << futureValue << "\n";
    }

    // Monetary change: Exact integer arithmetic avoiding roundoff
    int totalCents = 0;
    if (std::cin >> totalCents) {
        int dollars = totalCents / 100;
        int remainingCents = totalCents % 100;
        std::cout << totalCents << " cents represents " 
                  << dollars << " dollars and " 
                  << remainingCents << " cents\n";
    }

    return 0;
}
